        <mesh rotation={[Math.PI / 2, 0, 0]}>
          <torusGeometry args={[radius, 0.018, 8, 160]} />
          <meshStandardMaterial color={theme.foreground} emissive={theme.foreground} emissiveIntensity={0.4} />
